args.ReplacementContent:
for await (const line of rl) {
  try {
    const obj = JSON.parse(line);
    if ([1144, 1154, 1345].includes(obj.step_index)) {
      console.log('\n--- FOUND TOOL CALL FOR INDEX:', obj.step_index, '---');
      if (obj.tool_calls) {
        obj.tool_calls.forEach(tc => {
          console.log('Tool Name:', tc.name);
          if (tc.arguments) {
            console.log('TargetFile:', tc.arguments.TargetFile);
            if (tc.arguments.ReplacementContent) {
              console.log('ReplacementContent Length:', tc.arguments.ReplacementContent.length);
              fs.writeFileSync(`scratch/extracted_html_${obj.step_index}.txt`, tc.arguments.ReplacementContent, 'utf8');
              console.log(`Saved to scratch/extracted_html_${obj.step_index}.txt`);
            }
            if (tc.arguments.CodeContent) {
              console.log('CodeContent Length:', tc.arguments.CodeContent.length);
              fs.writeFileSync(`scratch/extracted_html_${obj.step_index}.txt`, tc.arguments.CodeContent, 'utf8');
              console.log(`Saved to scratch/extracted_html_${obj.step_index}.txt`);
            }
          }
        });
      }
    }
  } catch (err) {
    // ignore
  }
}

args.TargetContent:
for await (const line of rl) {
  if (line.includes('explorer-operational-tab-content')) {
    try {
      const obj = JSON.parse(line);
      if (obj.tool_calls) {
        console.log('\n--- FOUND TOOL CALL ---');
        console.log('Step Index:', obj.step_index);
        console.log('Type:', obj.type);
        obj.tool_calls.forEach(tc => {
          if (tc.arguments && tc.arguments.ReplacementContent) {
            console.log('ReplacementContent Length:', tc.arguments.ReplacementContent.length);
            console.log('Preview:');
            console.log(tc.arguments.ReplacementContent.substring(0, 1500));
          }
        });
      }
    } catch (err) {
      // ignore JSON parse error for partial lines
    }
  }
}
